// llm/client.rs
use crate::types::{Action, Observation};

#[async_trait::async_trait]
pub trait LlmClient: Send + Sync {
    async fn propose_action(
        &self,
        task: &str,
        plan: Option<&str>,
        obs: &Observation,
        history: &[String],
    ) -> anyhow::Result<Action>;
}
