#[derive(Debug)]
pub enum ConfigError {
    Io { path: PathBuf, message: String },
    Toml { path: PathBuf, message: String },
    Env { name: String, message: String },
    Invalid { message: String },
}

impl ConfigError {
    fn invalid(message: impl Into<String>) -> Self {
        ConfigError::Invalid {
            message: message.into(),
        }
    }
}

impl fmt::Display for ConfigError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ConfigError::Io { path, message } => {
                write!(f, "failed to read config {}: {message}", path.display())
            }
            ConfigError::Toml { path, message } => {
                write!(f, "failed to parse config {}: {message}", path.display())
            }
            ConfigError::Env { name, message } => {
                write!(f, "invalid env {name}: {message}")
            }
            ConfigError::Invalid { message } => write!(f, "{message}"),
        }
    }
}

impl std::error::Error for ConfigError {}

pub fn load_config(config_path: Option<&Path>, cli: CliOverrides) -> Result<AppConfig, ConfigError> {
    let mut config = AppConfig::default();

    if let Some(path) = config_path {
        let file_config = FileConfig::from_path(path)?;
        file_config.apply(&mut config)?;
    }

    let env_overrides = EnvOverrides::from_env()?;
    env_overrides.apply(&mut config)?;

    cli.apply(&mut config)?;

    Ok(config)
}

#[derive(Clone, Debug, Default, Deserialize)]
struct FileConfig {
    #[serde(default)]
    agent: Option<FileAgentConfig>,
    #[serde(default)]
    browser: Option<FileBrowserConfig>,
    #[serde(default)]
    router: Option<FileRouterConfig>,
    #[serde(default)]
    validator: Option<FileValidatorConfig>,
    #[serde(default)]
    llm: Option<FileLlmConfig>,
    #[serde(default)]
    output: Option<FileOutputConfig>,
}

impl FileConfig {
    fn from_path(path: &Path) -> Result<Self, ConfigError> {
        let content = std::fs::read_to_string(path).map_err(|err| ConfigError::Io {
            path: path.to_path_buf(),
            message: err.to_string(),
        })?;
        toml::from_str(&content).map_err(|err| ConfigError::Toml {
            path: path.to_path_buf(),
            message: err.to_string(),
        })
    }

    fn apply(&self, config: &mut AppConfig) -> Result<(), ConfigError> {
        if let Some(agent) = self.agent.as_ref() {
            if let Some(max_steps) = agent.max_steps {
                config.agent.max_steps = max_steps;
            }
            if let Some(memory) = agent.memory.as_ref() {
                if let Some(max_obs) = memory.max_observations {
                    config.agent.memory.max_observations = max_obs;
                }
                if let Some(max_history) = memory.max_history {
                    config.agent.memory.max_history = max_history;
                }
            }
        }

        if let Some(browser) = self.browser.as_ref() {
            apply_headless(&mut config.browser, browser.headless, browser.headful)?;
            if let Some(initial_url) = browser.initial_url.as_ref() {
                config.browser.initial_url = initial_url.to_string();
            }
            if let Some(cdp_url) = browser.cdp_url.as_ref() {
                config.browser.cdp_url = Some(cdp_url.to_string());
            }
            if let Some(timeout_ms) = browser.snapshot_timeout_ms {
                config.browser.snapshot_timeout = Duration::from_millis(timeout_ms);
            }
            if let Some(timeout_ms) = browser.action_timeout_ms {
                config.browser.action_timeout = Duration::from_millis(timeout_ms);
            }
            if let Some(max_elements) = browser.max_elements {
                config.browser.max_elements = max_elements;
            }
            if let Some(max_text_len) = browser.max_text_len {
                config.browser.max_text_len = max_text_len;
            }
        }

        if let Some(output) = self.output.as_ref() {
            if let Some(path) = output.extract_output.as_ref() {
                config.output.extract_output = Some(PathBuf::from(path));
            }
        }

async fn run_command(args: RunArgs) -> Result<(), Box<dyn Error>> {
    let task = resolve_required_text("task", args.task.as_deref(), args.task_file.as_deref())?;
    let plan = resolve_optional_text("plan", args.plan.as_deref(), args.plan_file.as_deref())?;

    let config_path = resolve_config_path(args.config.as_deref());
    let cli_overrides = build_cli_overrides(&args)?;
    let config = load_config(config_path.as_deref(), cli_overrides)?;

    emit_json(&ConfigLog::from(&config))?;
    let repair_start = telemetry::snapshot();
    let execution = match execute_agent(&task, plan.as_deref(), &config).await {
        Ok(execution) => execution,
        Err(err) => {
            let repair_counts = repair_counts_delta(&repair_start, &telemetry::snapshot());
            let summary = mbus::output::build_run_summary(
                mbus::output::TerminalState::Error,
                &[],
                vec![run_error_summary(
                    "startup_error",
                    err.to_string(),
                    Some("startup"),
                )],
                Vec::new(),
                repair_counts,
            );
            emit_run_logs(&[], &summary, None, None)?;
            return Err(err);
        }
    };

    let RunExecution {
        result,
        steps,
        final_observation,
    } = execution;

    let mut errors = Vec::new();
    let mut output_artifacts = Vec::new();
    let mut final_action = None;
    let mut terminal_state = mbus::output::TerminalState::Error;
    let mut return_error: Option<Box<dyn Error>> = None;

    match result {
        Ok(result) => {
            terminal_state = match result.status {
                RunStatus::Done => mbus::output::TerminalState::Done,
                RunStatus::MaxSteps => mbus::output::TerminalState::MaxSteps,
            };
            final_action = Some(result.final_action);
        }
        Err(err) => {
            errors.push(agent_error_summary(&err));
            if return_error.is_none() {
                return_error = Some(Box::new(err));
            }
        }
    }

    match write_extract_output(&task, &config, &steps) {
        Ok(Some(artifact)) => output_artifacts.push(artifact),
        Ok(None) => {}
        Err(err) => {
            errors.push(run_error_summary(
                "output_error",
                err.to_string(),
                Some("output"),
            ));
            if return_error.is_none() {
                return_error = Some(err);
            }
        }
    }

    let repair_counts = repair_counts_delta(&repair_start, &telemetry::snapshot());
    let summary = mbus::output::build_run_summary(
        terminal_state,
        &steps,
        errors,
        output_artifacts,
        repair_counts,
    );
    emit_run_logs(
        &steps,
        &summary,
        final_action.as_ref(),
        final_observation.as_ref(),
    )?;

    if let Some(err) = return_error {
        return Err(err);
    }

    Ok(())
}

async fn bench_command(args: BenchArgs) -> Result<(), Box<dyn Error>> {
    let tasks_dir = args.tasks_dir.unwrap_or_else(tasks_dir_default);
    let report_path = args.report_path.unwrap_or_else(report_path_default);
    let max_steps_per_task = args.max_steps_per_task.unwrap_or(40);

    let tasks = load_tasks(&tasks_dir).map_err(|err| format!("bench tasks: {err}"))?;
    let total_tasks = tasks.len();
    let required_passes = args
        .required_passes
        .unwrap_or_else(|| total_tasks.saturating_sub(2));

    let config_path = resolve_config_path(args.config.as_deref());
    let cli_overrides = CliOverrides {
        headless: args.headless,
        max_steps: Some(max_steps_per_task),
        llm_mode: Some(LlmMode::Scripted),
        extract_output: None,
        ..CliOverrides::default()
    };
    let base_config = load_config(config_path.as_deref(), cli_overrides)?;

    let server = BenchServer::start()
        .await
        .map_err(|err| format!("bench server startup failed: {err}"))?;
    let base_url = server.base_url();

    emit_json(&BenchConfigLog {
        r#type: "bench_config",
        tasks_dir: tasks_dir.display().to_string(),
        report_path: report_path.display().to_string(),
        max_steps_per_task,
        required_passes,
        base_url: base_url.clone(),
    })?;

    let actions_dir = actions_work_dir(&report_path);
    let mut results = Vec::with_capacity(tasks.len());

    for task in tasks {
        let started_at = std::time::Instant::now();
        let mut task_config = base_config.clone();
        let step_limit = bench_task_limit(&task, max_steps_per_task);
        task_config.agent.max_steps = step_limit;
        task_config.browser.initial_url = join_base_url(&base_url, &task.start_path);
        task_config.llm.mode = LlmMode::Scripted;

        let actions_json = render_actions(&task.actions, &base_url)
            .map_err(|err| format!("task {} actions: {err}", task.id))?;
        let actions_file = actions_file_path(&actions_dir, &task.id);
        write_actions_file(&actions_file, &actions_json)
            .map_err(|err| format!("task {} actions file: {err}", task.id))?;
        task_config.llm.actions_file = Some(actions_file);

        let run = execute_agent(&task.task, task.plan.as_deref(), &task_config).await;
        let elapsed = started_at.elapsed().as_millis() as u64;
        let task_result = match run {
            Ok(execution) => match execution.result {
                Ok(result) => {
                    let observed_status = match result.status {
                        RunStatus::Done => BenchObservedStatus::Done,
                        RunStatus::MaxSteps => BenchObservedStatus::MaxSteps,
                    };
                    let mut evaluated = evaluate_task(
                        &task,
                        observed_status,
                        result.steps.len(),
                        Some(&result.final_observation.url),
                        Some(&result.final_observation.visible_text),
                        step_limit,
                        None,
                    );
                    evaluated.duration_ms = elapsed;
                    evaluated
                }
                Err(err) => {
                    let mut evaluated = evaluate_task(
                        &task,
                        BenchObservedStatus::Error,
                        execution.steps.len(),
                        None,
                        None,
                        step_limit,
                        Some(&err.to_string()),
                    );
                    evaluated.duration_ms = elapsed;

